<template>
  <AppLayout>
    <div class="quality-page">
      <header class="quality-heading">
        <div><div class="eyebrow"><span></span> ACCOUNT QUALITY WATCH</div><h1>降智检查<span class="heading-tag">BETA</span></h1><p>用同样的两道题，持续观察每个账号的回答表现。</p></div>
        <div class="schedule-summary"><span class="schedule-orbit">◷</span><div><small>{{ overview?.config.enabled ? '下一轮自动检查' : '自动检查已暂停' }}</small><strong>{{ nextCountdown }}</strong></div></div>
      </header>
      <p v-if="error" class="message error" role="alert">{{ error }}</p>
      <p v-if="notice" class="message" role="status">{{ notice }}</p>

      <section class="quality-controls">
        <div class="auto-control"><button type="button" role="switch" :aria-checked="!!overview?.config.enabled" aria-label="自动检查" class="toggle" :class="{ on: overview?.config.enabled }" :disabled="busy || !overview" @click="toggleSchedule"><span></span></button><div><b>每 10 分钟自动检查</b><small>关闭页面后继续运行</small></div></div>
        <div class="model-control"><label for="quality-model">检查模型</label><input id="quality-model" v-model="model" maxlength="200" placeholder="gpt-6-astra" :disabled="busy"><button type="button" :disabled="busy || !model.trim() || model === overview?.config.model" @click="saveModel">保存</button></div>
        <button class="run-button" type="button" :disabled="busy || !eligibleCount" @click="runNow()"><span>↻</span> 立即检查全部</button>
      </section>

      <div class="overview-metrics">
        <div><span class="metric-icon teal">◎</span><p>纳入检查的账号<strong>{{ eligibleCount }}<small>个账号</small></strong></p></div>
        <div><span class="metric-icon blue">◷</span><p>固定检查频率<strong>10<small>分钟 / 轮</small></strong></p></div>
        <div><span class="metric-icon amber">◈</span><p>答案或输出需复核<strong>{{ reviewCount }}<small>个账号</small></strong></p></div>
        <div><span class="metric-icon purple">↗</span><p>正在检查<strong>{{ runningCount }}<small>逐账号执行</small></strong></p></div>
      </div>

      <div class="account-toolbar"><div class="tabs"><button v-for="tab in filters" :key="tab.value" type="button" :class="{ active: filter === tab.value }" @click="filter = tab.value">{{ tab.label }}</button></div><span class="sync-note"><i :class="{ stale: !!error }"></i>{{ error ? '更新中断' : '每 5 秒更新结果' }}</span></div>
      <div v-if="!overview" class="empty-state">正在读取账号检查状态…</div>
      <div v-else-if="!shownAccounts.length" class="empty-state">{{ overview.accounts.length ? '当前筛选下没有账号' : '还没有账号，添加后会自动纳入检查' }}</div>
      <div class="account-grid">
        <article v-for="account in shownAccounts" :key="account.id" class="account-card" :class="{ checking: account.latest?.status === 'running' }">
          <div class="account-header"><div class="account-avatar">{{ account.name.slice(0, 1).toUpperCase() || 'A' }}</div><div class="account-identity"><h2>{{ account.name }}</h2><span>{{ account.platform.toUpperCase() }} <i>·</i> #{{ String(account.id).padStart(3, '0') }}</span></div><span class="status-pill" :class="accountTone(account)">{{ accountStatus(account) }}</span></div>
          <div class="account-meta"><code>{{ account.latest?.model || overview?.config.model }}</code><span>{{ account.latest ? date(account.latest.started_at) : '等待首次检查' }}</span></div>
          <div class="case-grid">
            <button class="case-preview" type="button" :disabled="!getCase(account, 'goose_svg')" :aria-label="`${account.name}：放大小鹅骑车 SVG`" @click="openCase(account, 'goose_svg')">
              <div class="case-label"><span><b>01</b> 小鹅骑车</span><span class="expand-icon">⤢</span></div>
              <div class="svg-thumbnail"><img v-if="svgPreview(account)" :src="svgPreview(account)" alt="该账号生成的小鹅骑自行车 SVG"><div v-else class="preview-placeholder"><span>{{ getCase(account, 'goose_svg')?.status === 'error' ? '!' : '✧' }}</span><small>{{ casePlaceholder(account, 'goose_svg') }}</small></div></div>
              <div class="case-bottom"><span :class="getCase(account, 'goose_svg')?.status">{{ caseLabel(getCase(account, 'goose_svg')) }}</span><small>{{ caseDuration(getCase(account, 'goose_svg')) }}</small></div>
              <div class="ticket-badge" :class="getCase(account, 'goose_svg')?.ticket?.status" :title="ticketDetail(getCase(account, 'goose_svg'))">{{ ticketLabel(getCase(account, 'goose_svg')) }}</div>
            </button>
            <button class="case-preview" type="button" :disabled="!getCase(account, 'candy')" :aria-label="`${account.name}：展开糖果题回答`" @click="openCase(account, 'candy')">
              <div class="case-label"><span><b>02</b> 糖果推理</span><span class="expand-icon">⤢</span></div>
              <div class="candy-thumbnail"><template v-if="getCase(account, 'candy')"><div class="answer-number">{{ getCase(account, 'candy')?.answer ?? '—' }}<small>颗</small><span :class="getCase(account, 'candy')?.status">{{ caseLabel(getCase(account, 'candy')) }}</span></div><p>{{ candyExcerpt(getCase(account, 'candy')) }}</p></template><div v-else class="preview-placeholder"><span>◇</span><small>{{ casePlaceholder(account, 'candy') }}</small></div></div>
              <div class="case-bottom"><span>点击查看完整推导</span><small>{{ caseDuration(getCase(account, 'candy')) }}</small></div>
              <div class="ticket-badge" :class="getCase(account, 'candy')?.ticket?.status" :title="ticketDetail(getCase(account, 'candy'))">{{ ticketLabel(getCase(account, 'candy')) }}</div>
            </button>
          </div>
          <p class="account-note">{{ accountNote(account) }}</p>
          <footer class="account-footer"><span><i></i>{{ account.eligible ? account.latest?.status === 'running' ? '检查进行中' : overview?.config.enabled ? '下次 '+countdown(account.next_run_at) : '自动检查已暂停' : '当前账号不参与检查' }}</span><div><button type="button" :disabled="!account.latest" @click="showHistory(account)">历史记录</button><button type="button" :disabled="busy || !account.eligible || account.latest?.status === 'running'" @click="runNow(account.id)">检查一次 ↗</button></div></footer>
        </article>
      </div>

      <details class="method-card"><summary><span>◈ 检查题目与判定说明</span><span>查看规则 ＋</span></summary><div class="method-grid"><section><h3>01 · 小鹅骑自行车</h3><p>检查 SVG 是否完整、可解析。画面是否准确表现小鹅骑车，需要点击缩略图目测；结构通过不等于画面质量通过。</p><pre>{{ overview?.goose_prompt }}</pre></section><section><h3>02 · 糖果推理</h3><p>按题目给出的固定摸取数量，最大不满足集合为 28 颗，因此保证值是 29 颗。自动判断只核对最终数值，推导需展开核验。</p><pre>{{ overview?.candy_prompt }}</pre></section></div></details>
      <p class="page-footnote">每题发出前同步该账号与实际模型的最新有效票据；票据开启时，缺票或过期会等待下轮。每轮两次调用消耗账号额度。结果记录本次使用的票据状态，旧记录不会随票据刷新而改变。两道题不能单独证明模型降级，保留最近 36 轮。</p>
    </div>

    <BaseDialog :show="!!selected" :title="selected ? `${selected.accountName} · ${selected.result.kind === 'goose_svg' ? '小鹅骑自行车' : '糖果推理'}` : ''" width="extra-wide" @close="selected = null">
      <div v-if="selected" class="quality-detail"><div class="detail-meta"><span>{{ date(selected.startedAt) }} · {{ selected.result.model || selected.model }}</span><span>{{ (selected.result.latency_ms / 1000).toFixed(1) }} s · {{ selected.result.characters.toLocaleString() }} 字符</span></div><p class="ticket-detail" :class="selected.result.ticket?.status">{{ ticketDetail(selected.result) }}</p><p class="detail-verdict" :class="selected.result.status">{{ selected.result.note }}</p><img v-if="selected.result.kind === 'goose_svg' && selectedSvg" class="svg-large" :src="selectedSvg" alt="放大查看小鹅骑自行车 SVG"><pre v-if="selected.result.kind !== 'goose_svg'" class="answer-full">{{ selected.result.text || selected.result.note }}</pre><details v-else class="source-details"><summary>查看 SVG 原始输出</summary><pre class="answer-full">{{ selected.result.text || selected.result.note }}</pre></details></div>
    </BaseDialog>
    <BaseDialog :show="!!historyAccount" :title="`${historyAccount?.name || ''} · 最近检查记录`" width="wide" @close="historyAccount = null">
      <div class="quality-history"><p v-if="historyLoading">正在读取…</p><p v-else-if="!history.length">暂无检查记录</p><div v-for="run in history" :key="run.id" class="history-row"><div><strong>{{ date(run.started_at) }}</strong><small>{{ run.model }} · {{ run.status === 'completed' ? '已完成' : run.status === 'running' ? '进行中' : '已中断' }}</small></div><button type="button" @click="openHistoryCase(run.id, 'goose_svg')">SVG ⤢</button><button type="button" @click="openHistoryCase(run.id, 'candy')">糖果题 ↗</button></div></div>
    </BaseDialog>
  </AppLayout>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import AppLayout from '@/components/layout/AppLayout.vue'
import BaseDialog from '@/components/common/BaseDialog.vue'
import { configureQuality, getQualityHistory, getQualityOverview, getQualityRun, runQuality, type QualityAccount, type QualityCase, type QualityOverview, type QualityRun } from '@/api/admin/qualityChecks'
import { qualitySvgDataUrl } from '@/utils/qualityPreview'

const overview = ref<QualityOverview | null>(null), model = ref(''), error = ref(''), notice = ref(''), busy = ref(false), filter = ref('all'), now = ref(Date.now())
const filters = [{ value: 'all', label: '全部账号' }, { value: 'attention', label: '需复核' }, { value: 'error', label: '调用异常' }, { value: 'waiting', label: '等票据' }]
const selected = ref<{ accountName: string; model: string; startedAt: string; result: QualityCase } | null>(null)
const historyAccount = ref<QualityAccount | null>(null), history = ref<QualityRun[]>([]), historyLoading = ref(false)
let pollTimer: ReturnType<typeof setTimeout> | undefined, clockTimer: ReturnType<typeof setInterval> | undefined, disposed = false, loading = false, serverOffset = 0
const accounts = computed(() => overview.value?.accounts || [])
const eligibleCount = computed(() => accounts.value.filter(a => a.eligible).length)
const runningCount = computed(() => accounts.value.filter(a => a.latest?.status === 'running').length)
const needsReview = (a: QualityAccount) => a.latest?.cases.some(c => c.status === 'mismatch' || (c.kind === 'candy' && c.status === 'review')) || a.latest?.status === 'interrupted'
const hasError = (a: QualityAccount) => a.latest?.cases.some(c => c.status === 'error')
const waitingTicket = (a: QualityAccount) => a.latest?.cases.some(c => c.status === 'waiting_ticket')
const reviewCount = computed(() => accounts.value.filter(needsReview).length)
const shownAccounts = computed(() => accounts.value.filter(a => filter.value === 'all' || (filter.value === 'attention' ? needsReview(a) : filter.value === 'waiting' ? waitingTicket(a) : hasError(a))))
const getCase = (a: QualityAccount, kind: string) => a.latest?.cases.find(c => c.kind === kind)
const selectedSvg = computed(() => selected.value ? qualitySvgDataUrl(selected.value.result.text) : '')
const previews = computed(() => new Map(accounts.value.map(a => [a.id, qualitySvgDataUrl(getCase(a, 'goose_svg')?.text || '')])))
const svgPreview = (a: QualityAccount) => previews.value.get(a.id) || ''
const date = (s: string) => new Date(s).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false })
function countdown(s: string | null) { if (!s) return '待调度'; const n = Math.max(0, Math.ceil((Date.parse(s) - now.value - serverOffset) / 1000)); return n ? `${String(Math.floor(n / 60)).padStart(2, '0')}:${String(n % 60).padStart(2, '0')}` : '即将开始' }
const nextCountdown = computed(() => { if (!overview.value?.config.enabled) return '已暂停'; const times = accounts.value.filter(a => a.eligible && a.next_run_at).map(a => a.next_run_at!).sort(); return times.length ? countdown(times[0]) : '准备首次检查' })
const caseLabel = (c?: QualityCase) => !c ? '等待结果' : ({ pass: '数值符合', review: c.kind === 'goose_svg' ? '待目测' : '待复核', mismatch: '需复核', error: '调用异常', waiting_ticket: '等待有效票据' }[c.status] || c.status)
const ticketLabel = (c?: QualityCase) => !c ? '发出前同步票据' : !c.ticket ? '历史记录 · 未记录票据' : c.ticket.status === 'injected' ? `已注入票据 · ${c.ticket.length} 字符` : ({ missing: '缺少票据 · 本题未发送', expired: '票据过期 · 本题未发送', unavailable: '票据服务未就绪', disabled: '票据功能已关闭 · 未注入', not_required: '该模型未启用票据', not_applicable: '此账号无需票据', unverified: '尚未进入票据注入步骤' }[c.ticket.status] || '未记录票据')
function ticketDetail(c?: QualityCase) { const t = c?.ticket; return [ticketLabel(c), t?.account_id ? `账号 #${t.account_id} · ${t.model}` : '', t?.captured_at ? `获取 ${date(t.captured_at)}` : '', t?.expires_at ? `有效至 ${date(t.expires_at)}` : ''].filter(Boolean).join('；') }
const caseDuration = (c?: QualityCase) => c ? `${(c.latency_ms / 1000).toFixed(1)} s` : '—'
const casePlaceholder = (a: QualityAccount, kind: string) => getCase(a, kind)?.status === 'waiting_ticket' ? '等待有效票据，本题未发送' : getCase(a, kind)?.status === 'error' ? '调用失败，点击查看' : a.latest?.status === 'running' ? kind === 'candy' && !getCase(a, 'goose_svg') ? '等待上一题完成' : '正在生成回答…' : '本轮输出将在这里显示'
const candyExcerpt = (c?: QualityCase) => c && ['error', 'waiting_ticket'].includes(c.status) ? c.note : (c?.text || '').replace(/[#*`]/g, '').slice(0, 180)
function accountTone(a: QualityAccount) { return a.latest?.status === 'running' ? 'running' : hasError(a) ? 'error' : waitingTicket(a) ? 'waiting_ticket' : needsReview(a) ? 'mismatch' : a.latest ? 'review' : 'idle' }
function accountStatus(a: QualityAccount) { if (!a.eligible) return a.platform !== 'openai' ? '暂不支持' : '已停用'; return a.latest?.status === 'running' ? '检查中' : hasError(a) ? '调用异常' : waitingTicket(a) ? '等待票据' : needsReview(a) ? '需复核' : a.latest ? '待目测 SVG' : '待检查' }
function accountNote(a: QualityAccount) { if (!a.eligible) return a.platform === 'openai' ? '账号已停用，不发起自动请求。' : '当前检查支持 OpenAI 文本账号。'; const unusual = a.latest?.cases.find(c => ['error', 'mismatch', 'waiting_ticket'].includes(c.status)); return unusual?.note || (a.latest?.status === 'interrupted' ? '上一轮因服务重启等原因中断，下轮会重新检查。' : '缩略图与回答均可点击放大，SVG 画面请人工核验。') }
function message(e: unknown) { return e && typeof e === 'object' && 'message' in e ? String(e.message) : '操作失败，请稍后重试' }
async function refresh() { if (loading || disposed) return; loading = true; try { const data = await getQualityOverview(); if (disposed) return; const previous = overview.value?.config.model; overview.value = data; serverOffset = Date.parse(data.server_time) - Date.now(); if (!model.value || model.value === previous) model.value = data.config.model; error.value = '' } catch (e) { error.value = message(e) } finally { loading = false; clearTimeout(pollTimer); if (!disposed) pollTimer = setTimeout(refresh, 5000) } }
async function configure(enabled: boolean) { if (!overview.value) return; busy.value = true; error.value = ''; try { await configureQuality({ enabled, model: model.value.trim(), interval_seconds: 600 }); notice.value = enabled ? '自动检查已开启，每个账号每 10 分钟检查一次。' : '自动检查已暂停，正在运行的本轮会完成。'; await refresh() } catch (e) { error.value = message(e) } finally { busy.value = false } }
const toggleSchedule = () => configure(!overview.value?.config.enabled)
const saveModel = () => configure(!!overview.value?.config.enabled)
async function runNow(id = 0) { busy.value = true; try { const r = await runQuality(id); notice.value = r.started ? `已启动 ${r.started} 个账号的检查。` : '账号正在检查中，或暂无可检查账号。'; await refresh() } catch (e) { error.value = message(e) } finally { busy.value = false } }
function openCase(a: QualityAccount, kind: string) { const result = getCase(a, kind); if (result && a.latest) selected.value = { accountName: a.name, model: a.latest.model, startedAt: a.latest.started_at, result } }
async function showHistory(a: QualityAccount) { historyAccount.value = a; history.value = []; historyLoading.value = true; try { history.value = await getQualityHistory(a.id) } catch (e) { error.value = message(e) } finally { historyLoading.value = false } }
async function openHistoryCase(id: number, kind: string) { try { const run = await getQualityRun(id), result = run.cases.find(c => c.kind === kind); if (!result) { notice.value = '该题尚无结果。'; return } const accountName = historyAccount.value?.name || `账号 #${run.account_id}`; historyAccount.value = null; selected.value = { accountName, model: run.model, startedAt: run.started_at, result } } catch (e) { error.value = message(e) } }
onMounted(() => { refresh(); clockTimer = setInterval(() => { now.value = Date.now() }, 1000) })
onUnmounted(() => { disposed = true; clearTimeout(pollTimer); clearInterval(clockTimer) })
</script>

<style scoped>
